INSERT INTO academic_item_options (academic_item_id, option_text, is_correct) VALUES
  (253, 'An architecture where the application is a set of small independent services, each with one business capability, its own process and its own data, communicating over the network', TRUE),
  (253, 'An architecture where the application is one deployable unit split into folders, with one shared process and one shared database', FALSE),
  (253, 'An architecture where the application is a set of small functions run by a scheduler with no network communication', FALSE),
  (254, 'An application built and deployed as a single unit, with all modules sharing one codebase, one process and usually one database', TRUE),
  (254, 'An application split into independent services that are deployed separately and own their own databases', FALSE),
  (254, 'An application that runs only on one physical server and cannot use a database', FALSE),
  (255, 'A monolith deploys and scales as one unit; microservices deploy and scale independently and isolate failures but add network and operational complexity', TRUE),
  (255, 'A monolith deploys and scales per module; microservices deploy as one unit but isolate failures and reduce operational complexity', FALSE),
  (255, 'They differ only in programming language; deployment, scaling and failure handling are the same', FALSE),
  (256, 'Independent deployment and scaling, fault isolation, technology freedom, smaller codebases and small autonomous teams', TRUE),
  (256, 'Simpler deployment, easy cross-service transactions, one technology stack and less infrastructure cost', FALSE),
  (256, 'Faster local calls, a single database for all data, no network failures and easier debugging', FALSE),
  (257, 'Distributed system complexity, network latency and failures, data consistency, harder testing and debugging, strong DevOps needs and more infrastructure cost', TRUE),
  (257, 'Tight coupling between services, one point of failure, a single deployment and no need for monitoring', FALSE),
  (257, 'Slower development because all teams share code, plus limited choice of tools and databases', FALSE),
  (258, 'For small applications, small teams, early products with unclear boundaries, or teams without mature DevOps and monitoring', TRUE),
  (258, 'For large applications with many teams, stable domain boundaries and mature DevOps and monitoring', FALSE),
  (258, 'For applications that need independent scaling of parts and several programming languages', FALSE),
  (259, 'A single deployable application internally divided into well-separated modules with clear boundaries, making a later split into microservices easier', TRUE),
  (259, 'Several deployable applications that share one database and are released together on the same day', FALSE),
  (259, 'A single deployable application with no module boundaries where every class may call every other class', FALSE),
  (260, 'Split by business capability or DDD bounded contexts, not technical layers, aiming for high cohesion and loose coupling', TRUE),
  (260, 'Split by technical layers such as UI, business logic and data, aiming for the same team to own every layer', FALSE),
  (260, 'Split by database tables, creating one service per table and sharing the data through joins', FALSE),
  (261, 'A boundary within which a domain model and its terms have one clear meaning, often mapping to a microservice', TRUE),
  (261, 'A boundary around a database in which all tables must use the same naming convention', FALSE),
  (261, 'A boundary around a team in which every member must use the same programming language', FALSE),
  (262, 'Each service should do one thing well and own one business capability, so it has one reason to change', TRUE),
  (262, 'Each service should do many related things so it can serve all requests without calling other services', FALSE),
  (262, 'Each service should own one database table, so it has one reason to change', FALSE),
  (263, 'Each microservice owns its private database, and other services access that data only through the service API', TRUE),
  (263, 'All microservices share one database but use different schemas, and read each other tables directly', FALSE),
  (263, 'Each microservice owns a copy of one shared database, and changes are merged every night', FALSE),
  (264, 'It couples services: schema changes in one can break others, services cannot deploy independently and data ownership is unclear', TRUE),
  (264, 'It makes every query slower because a shared database cannot use indexes across services', FALSE),
  (264, 'It stops services from using transactions, so no data can be written by more than one service', FALSE),
  (265, 'Synchronous: the caller sends a request and waits (REST, gRPC); asynchronous: the sender publishes a message and continues, which reduces coupling', TRUE),
  (265, 'Synchronous: the sender publishes a message and continues (queues); asynchronous: the caller waits for a response (REST, gRPC)', FALSE),
  (265, 'Synchronous calls use HTTP only and asynchronous calls use databases only, with identical coupling', FALSE),
  (266, 'An architectural style for APIs over HTTP using resources identified by URLs and standard methods like GET, POST, PUT, PATCH and DELETE, typically with JSON', TRUE),
  (266, 'A binary protocol over HTTP/2 using generated contracts and streaming, typically with Protocol Buffers', FALSE),
  (266, 'A messaging style over a broker using topics and queues, typically with XML', FALSE),
  (267, 'A high-performance RPC framework over HTTP/2 with Protocol Buffers and strongly typed contracts, supporting streaming, often used internally', TRUE),
  (267, 'A text-based API style over HTTP/1.1 with JSON and URLs as resources, mostly used for public APIs', FALSE),
  (267, 'A message broker over TCP with topics and queues, mostly used for event streaming', FALSE),
  (268, 'Middleware that receives, stores and routes messages between services for asynchronous communication, such as RabbitMQ, Kafka, SQS/SNS and Service Bus', TRUE),
  (268, 'Middleware that translates HTTP requests into SQL queries for services, such as NGINX, Kong and HAProxy', FALSE),
  (268, 'Middleware that stores service configuration and secrets for services, such as Consul, Vault and etcd', FALSE),
  (269, 'In a queue each message is processed by one consumer; in publish/subscribe a message to a topic is delivered to all subscribers', TRUE),
  (269, 'In a queue each message is delivered to all consumers; in publish/subscribe each message is processed by one subscriber', FALSE),
  (269, 'Both deliver each message to exactly one consumer; pub/sub only adds message ordering', FALSE),
  (270, 'RabbitMQ is a broker with flexible routing that removes messages after delivery; Kafka is a distributed event log that stores ordered, replayable events at high throughput', TRUE),
  (270, 'Kafka is a broker with flexible routing that removes messages after delivery; RabbitMQ is a distributed event log with replayable events', FALSE),
  (270, 'Both are identical brokers; the only difference is that Kafka runs in the cloud', FALSE),
  (271, 'Services communicate by producing and reacting to events such as OrderPlaced; producers do not know the consumers, so the system is loosely coupled', TRUE),
  (271, 'Services communicate by calling each other directly and waiting for answers, so the system is tightly coupled', FALSE),
  (271, 'Services communicate by sharing a database table of events that producers and consumers both edit', FALSE),
  (272, 'A single entry point that routes requests to services and handles authentication, rate limiting, SSL termination, caching and aggregation, such as Kong or NGINX', TRUE),
  (272, 'A message broker that routes events between services and handles retries, ordering and dead letters, such as Kafka', FALSE),
  (272, 'A service registry that tracks service instances and handles health checks and discovery, such as Consul', FALSE),
  (273, 'A separate backend or gateway per client type such as web and mobile, so each client gets an API tailored to it', TRUE),
  (273, 'A single shared backend for all client types, so every client gets the same generic API', FALSE),
  (273, 'A separate database per client type, so each client reads its own copy of the data', FALSE),
  (274, 'How services find each other network locations dynamically as instances change, using a registry such as Consul, Eureka or Kubernetes DNS', TRUE),
  (274, 'How services are split by business capability as the system grows, using domain events such as OrderPlaced', FALSE),
  (274, 'How services are given fixed IP addresses by hand, using a configuration file such as hosts', FALSE),
  (275, 'In client-side discovery the client queries the registry and picks an instance; in server-side discovery a load balancer or router queries the registry and forwards the request', TRUE),
  (275, 'In client-side discovery a load balancer queries the registry and forwards the request; in server-side discovery the client picks an instance', FALSE),
  (275, 'Both use fixed addresses; they differ only in whether the registry is stored in a file or in memory', FALSE),
  (276, 'Services run multiple instances; load balancing spreads requests across healthy instances, improving performance and availability', TRUE),
  (276, 'Services run one instance; load balancing copies requests to every instance, improving data consistency', FALSE),
  (276, 'Services run multiple instances; load balancing sends all requests to the first instance, improving cache hits', FALSE),
  (277, 'One slow or failed service makes the services that call it slow or fail too, spreading the failure across the system', TRUE),
  (277, 'One failed database replica is replaced by another, so the failure stays inside a single service', FALSE),
  (277, 'A deployment fails in one Region and is rolled back automatically in every other Region', FALSE),
  (278, 'It monitors calls to a service, opens after too many failures to fail fast, then goes half-open to test with a few requests before closing', TRUE),
  (278, 'It monitors calls to a service, retries every failed call until it works, then closes when the queue is empty', FALSE),
  (278, 'It limits the number of requests per user, rejecting extra ones, then opens again at midnight', FALSE),
  (279, 'Retrying a failed call after growing delays such as 1s, 2s, 4s, often with random jitter, to handle temporary failures without overloading the service', TRUE),
  (279, 'Retrying a failed call immediately and repeatedly with no delay, to finish as fast as possible', FALSE),
  (279, 'Retrying a failed call after the same fixed delay for every attempt, to keep traffic constant', FALSE),
  (280, 'It isolates resources such as thread pools or connections per dependency, so a failure in one part cannot exhaust everything and crash the service', TRUE),
  (280, 'It opens after repeated failures and fails fast, so a failing dependency is not called until it recovers', FALSE),
  (280, 'It retries failed calls with growing delays, so a temporary failure does not overload the service', FALSE),
  (281, 'Without timeouts a call to a slow service can wait forever and block threads, causing cascading failures; every remote call needs one', TRUE),
  (281, 'Without timeouts every call fails instantly, so timeouts are needed to allow retries', FALSE),
  (281, 'Timeouts are only needed for database calls, because HTTP calls always finish on their own', FALSE),
  (282, 'An alternative response when a call fails, such as cached data, a default value or a friendly message, so the system degrades gracefully', TRUE),
  (282, 'A second identical call sent at the same time, whose answer replaces the first if it arrives sooner', FALSE),
  (282, 'A rollback of the last deployment when a call fails, so the old version serves the request', FALSE),
  (283, 'An operation is idempotent if doing it several times has the same effect as once; it prevents duplicates such as double charges when retries happen', TRUE),
  (283, 'An operation is idempotent if it always returns a different result; it prevents caching mistakes such as stale charges', FALSE),
  (283, 'An operation is idempotent if it runs inside a transaction; it prevents partial writes such as half-saved charges', FALSE),
  (284, 'Data across services may be temporarily inconsistent but becomes consistent after a short time as events or updates propagate', TRUE),
  (284, 'Data across services is always identical at every moment because all writes use one distributed lock', FALSE),
  (284, 'Data across services stays inconsistent until someone runs a manual reconciliation each night', FALSE),
  (285, 'During a network partition a distributed system must choose between Consistency and Availability; partition tolerance is required in practice', TRUE),
  (285, 'A distributed system can always provide Consistency, Availability and Partition tolerance together, if it has enough nodes', FALSE),
  (285, 'During a network partition a system must choose between Performance and Security; consistency is required in practice', FALSE),
  (286, 'Two-phase commit locks resources across services, is slow, reduces availability and couples services, and many brokers and NoSQL stores do not support it', TRUE),
  (286, 'Two-phase commit is not reliable because it never locks resources, so two services can write the same row', FALSE),
  (286, 'Two-phase commit is too fast, so services cannot keep up with the number of commits', FALSE),
  (287, 'A business transaction across services as a sequence of local transactions; if a step fails, compensating transactions undo previous steps', TRUE),
  (287, 'A business transaction across services held open by a distributed lock until every service commits at once', FALSE),
  (287, 'A business transaction across services that is copied to a queue and replayed until every service succeeds', FALSE),
  (288, 'In choreography each service reacts to events with no central controller; in orchestration a central orchestrator tells each service which step to run', TRUE),
  (288, 'In choreography a central controller tells each service which step to run; in orchestration each service reacts to events', FALSE),
  (288, 'Both use a central controller; choreography only differs in using HTTP instead of messages', FALSE),
  (289, 'The service saves its data change and the event to publish in an outbox table in one local transaction, and another process publishes the events from it', TRUE),
  (289, 'The service publishes the event first and saves its data change after, retrying until both succeed', FALSE),
  (289, 'The service saves its data in two databases at once using a distributed transaction', FALSE),
  (290, 'Command Query Responsibility Segregation separates the write model from the read model so each can be optimized and scaled independently', TRUE),
  (290, 'Command Query Replication Service copies the write model to the read model so both use the same schema', FALSE),
  (290, 'Cache Query Response Strategy stores query responses in a cache so reads never reach the database', FALSE),
  (291, 'Instead of storing only current state, the system stores every change as an immutable event and rebuilds state by replaying events, giving a full audit history', TRUE),
  (291, 'The system stores only the latest state and overwrites it on every change, keeping an audit log in files', FALSE),
  (291, 'The system stores events temporarily in a queue and deletes them after the state is updated', FALSE),
  (292, 'To answer a query needing data from several services, a composer such as the API Gateway calls each one and combines the results', TRUE),
  (292, 'To answer a query needing data from several services, the client calls a shared database that joins all of their tables', FALSE),
  (292, 'To answer a query needing data from several services, the first service calls the next one and forwards the raw request along the chain', FALSE),
  (293, 'Gradually migrating from a monolith: new features are built as microservices and old ones are replaced one by one behind a proxy until the monolith is retired', TRUE),
  (293, 'Rewriting the whole monolith as microservices in one release and switching all traffic over on one day', FALSE),
  (293, 'Running the monolith and the microservices with the same code and never retiring the monolith', FALSE),
  (294, 'Centralized authentication with an identity provider using OAuth 2.0 and OpenID Connect, tokens (often JWTs) validated at the gateway, permission checks in services and mTLS between services', TRUE),
  (294, 'Each service stores its own user passwords and checks them on every call, with plain HTTP between services', FALSE),
  (294, 'The API Gateway checks a shared password in a header, and services trust every internal call', FALSE),
  (295, 'A compact signed token with claims about the user such as id, roles and expiry, which services can verify with the signing key without asking the auth server each time', TRUE),
  (295, 'A compact encrypted session ID that services must send to the auth server on every request to look up the user', FALSE),
  (295, 'A compact database row with the user data that is copied to every service when the user signs in', FALSE),
  (296, 'An infrastructure layer, usually sidecar proxies, handling service-to-service communication such as mTLS, retries, timeouts, routing and observability without changing code', TRUE),
  (296, 'A shared library linked into every service that adds retries and timeouts and requires code changes in each one', FALSE),
  (296, 'A central API gateway at the edge that handles authentication for clients but not traffic between services', FALSE),
  (297, 'Logs (records of events), metrics (numbers such as latency and error rate) and traces (the path of a request across services)', TRUE),
  (297, 'Alerts (messages to on-call staff), dashboards (graphs of servers) and reports (monthly summaries of uptime)', FALSE),
  (297, 'Backups (copies of data), replicas (standby databases) and snapshots (point-in-time disk images)', FALSE),
  (298, 'Following a single request through all the services it touches using a trace ID passed with each call, showing where time was spent and errors happened', TRUE),
  (298, 'Recording the CPU and memory of each service every minute and drawing them as a graph over time', FALSE),
  (298, 'Copying every log line from all services into one file sorted by the time they were written', FALSE),
  (299, 'A unique ID attached to a request at the entry point and passed to every downstream service and log entry, so related logs can be found together', TRUE),
  (299, 'A unique ID assigned to each service instance when it starts, so its logs can be found by instance', FALSE),
  (299, 'A unique ID assigned to each database transaction, so rollbacks can be matched across services', FALSE),
  (300, 'An endpoint such as /health reporting whether a service is running; liveness shows if it should be restarted and readiness shows if it can receive traffic', TRUE),
  (300, 'An endpoint such as /health reporting the average response time; liveness shows if traffic is fast and readiness shows if the cache is warm', FALSE),
  (300, 'An endpoint such as /health that restarts the service on every call, so liveness and readiness are both always true', FALSE),
  (301, 'It checks that a provider API matches what its consumers expect without running the whole system; consumer-driven contracts such as Pact catch breaking changes early', TRUE),
  (301, 'It checks that the provider legal terms match what its consumers signed, without reading any code', FALSE),
  (301, 'It runs every service together in one environment and tests the full user journey from the UI', FALSE),
  (302, 'Each service is packaged as a container and run on an orchestrator like Kubernetes with its own CI/CD pipeline, using rolling, blue-green or canary releases', TRUE),
  (302, 'All services are copied by hand to one server and restarted together after each change by the operations team', FALSE),
  (302, 'Each service is compiled into one file that is merged into the monolith before it is deployed', FALSE);
INSERT INTO academic_item_options (academic_item_id, option_text, is_correct) VALUES
  (316, 'A proven, reusable solution to a common design problem; it is a template for structuring classes, not ready code', TRUE),
  (316, 'A ready-made library of classes that you install with Composer and call to solve a problem', FALSE),
  (316, 'A coding style guide that sets naming and indentation rules for all classes in a project', FALSE),
  (317, 'Creational (how objects are created), Structural (how objects are composed) and Behavioral (how objects communicate)', TRUE),
  (317, 'Creational (how objects communicate), Structural (how objects are created) and Behavioral (how objects are composed)', FALSE),
  (317, 'Frontend (how views are drawn), Backend (how data is stored) and Network (how requests are routed)', FALSE),
  (318, 'MVC: Models handle data and rules (Eloquent), Views handle presentation (Blade) and Controllers coordinate requests and responses', TRUE),
  (318, 'MVVM: Models hold state, ViewModels bind data to Blade and Controllers are not used', FALSE),
  (318, 'Microkernel: a tiny core loads every feature as a plugin, and there are no models or controllers', FALSE),
  (319, 'All requests enter through a single entry point, public/index.php, which boots the app and passes the request to the kernel and router', TRUE),
  (319, 'Each route file is its own entry point, and the web server picks the controller for every URL', FALSE),
  (319, 'Each controller is a separate PHP file in public, and the web server runs the one matching the URL', FALSE),
  (320, 'Laravel IoC container that manages class dependencies and performs dependency injection, resolving and building objects automatically', TRUE),
  (320, 'A Docker container that runs the Laravel application and its services in isolation from the host', FALSE),
  (320, 'A cache that stores service objects between requests so they are never built twice across users', FALSE),
  (321, 'A class receives its dependencies from outside, usually by constructor or method parameters, instead of creating them itself', TRUE),
  (321, 'A class creates all its dependencies itself inside the constructor so it is fully self-contained', FALSE),
  (321, 'A class reads its dependencies from global variables that the framework sets before each request', FALSE),
  (322, 'The framework, not your class, controls creating and supplying objects; your code depends on abstractions and the container picks the implementation', TRUE),
  (322, 'Your class controls creating every object it uses, and the framework only calls its handle method', FALSE),
  (322, 'The database controls creating objects, which are loaded from rows when the class is needed', FALSE),
  (323, 'bind creates a new instance on every resolve; singleton creates it once and reuses it; scoped is like singleton but reset between requests and jobs', TRUE),
  (323, 'bind creates the instance once and reuses it; singleton creates a new instance on every resolve; scoped is never reset', FALSE),
  (323, 'bind and singleton are the same; scoped only works inside Blade views', FALSE),
  (324, 'In a provider register method call $this->app->bind(PaymentGateway::class, StripeGateway::class); classes type-hinting the interface receive StripeGateway', TRUE),
  (324, 'In the controller constructor call new StripeGateway(); classes type-hinting the interface receive PaymentGateway', FALSE),
  (324, 'In config/app.php add an entry PaymentGateway => StripeGateway; classes type-hinting the interface receive both', FALSE),
  (325, 'It gives different implementations of the same interface to different classes, for example $this->app->when(PhotoController::class)->needs(Filesystem::class)->give(...)', TRUE),
  (325, 'It binds an interface only while a request is running and removes it afterwards, for example with app()->forgetInstance()', FALSE),
  (325, 'It binds an interface to the same implementation for every class and every environment, for example with bind()', FALSE),
  (326, 'The central place to bootstrap the app: register binds things into the container and boot runs after all providers register to set up events, routes and macros', TRUE),
  (326, 'A class that provides HTTP responses to clients: register serves GET requests and boot serves POST requests', FALSE),
  (326, 'A class that provides database connections: register opens them and boot closes them after each request', FALSE),
  (327, 'A static-looking interface to objects in the service container, like Cache, DB, Route and Log, keeping syntax short while the object can be swapped or mocked', TRUE),
  (327, 'A base class that every model must extend to get static methods like find and where', FALSE),
  (327, 'A static helper class holding global state that is shared by all requests', FALSE),
  (328, 'No: a facade uses __callStatic to resolve the real object from the container and forward the call, so it can be faked in tests', TRUE),
  (328, 'Yes: a facade is a real static class whose methods run directly, so it cannot be faked in tests', FALSE),
  (328, 'No: a facade uses __construct to build a new object on every call, so it cannot be faked in tests', FALSE),
  (329, 'Both resolve objects from the container; DI makes dependencies explicit in the constructor, which is clearer and easier to test, while facades are shorter but hide dependencies', TRUE),
  (329, 'Facades make dependencies explicit and are easier to test; dependency injection hides them and is shorter to write', FALSE),
  (329, 'They resolve objects from different containers, and facades cannot be used inside classes', FALSE),
  (330, 'Prefixing an imported class with Facades makes any class usable as a facade without writing a facade class; Laravel generates it', TRUE),
  (330, 'Facades that refresh automatically when the underlying class changes, so cached results are never stale', FALSE),
  (330, 'Facades that run asynchronously on a queue so slow calls never block the request', FALSE),
  (331, 'A layer between business logic and data access: a repository class, often behind an interface, holds the queries so services do not know how data is stored', TRUE),
  (331, 'A layer between the browser and the controller: a repository class holds the routes so controllers do not know the URLs', FALSE),
  (331, 'A layer between models and the database: a repository class holds the migrations so models do not know the schema', FALSE),
  (332, 'Pros: centralized queries, easy to swap the data source and mock; cons: Eloquent is already an abstraction, so repositories can add boilerplate', TRUE),
  (332, 'Pros: Eloquent features are doubled and queries run faster; cons: repositories cannot be mocked in tests', FALSE),
  (332, 'Pros: no interfaces or queries to maintain; cons: the data source can never be swapped', FALSE),
  (333, 'Service classes hold business logic that does not belong in controllers or models, keeping controllers thin and the logic reusable from jobs and commands', TRUE),
  (333, 'Service classes hold routes and middleware for each feature, keeping the route files small', FALSE),
  (333, 'Service classes hold database migrations for each feature, keeping the models small', FALSE),
  (334, 'A small class that performs a single task, usually with one public method like handle or execute, such as CreateInvoiceAction', TRUE),
  (334, 'A small class that groups all methods of one model, with many public methods such as create, update and delete', FALSE),
  (334, 'A small class that stores the button clicks of a form and replays them later in the controller', FALSE),
  (335, 'A simple object that carries structured, typed data between layers, replacing loose arrays with type safety and clear contracts', TRUE),
  (335, 'A database table that stores transfer records between two accounts with typed columns', FALSE),
  (335, 'A class that sends data to another server over HTTP using typed requests', FALSE),
  (336, 'Each model object represents a table row and holds both data and persistence methods like save, update and delete; Eloquent implements it', TRUE),
  (336, 'Each model object is a plain data holder and a separate mapper saves it; Eloquent implements it', FALSE),
  (336, 'Each model object represents a whole table and is created once per request; Eloquent implements it', FALSE),
  (337, 'In Active Record the model saves itself; in Data Mapper entities are plain objects and a separate mapper handles persistence, as in Doctrine', TRUE),
  (337, 'In Data Mapper the model saves itself, as in Eloquent; in Active Record entities are plain objects and a mapper handles persistence', FALSE),
  (337, 'They differ only in file names; both store persistence methods in the entity class', FALSE),
  (338, 'It constructs complex objects step by step; Query Builder and Eloquent Builder chain where, orderBy and limit and build the SQL when get or first is called', TRUE),
  (338, 'It constructs one object at a time with a single constructor call; Query Builder runs the SQL after every chained method', FALSE),
  (338, 'It copies existing objects to create new ones; Query Builder clones the last query for each call', FALSE),
  (339, 'Each method returns the object itself so calls can be chained, as in User::where(...)->orderBy(...)->take(10)->get()', TRUE),
  (339, 'Each method returns a new database connection so calls run in parallel, as in User::where(...)->orderBy(...)->take(10)->get()', FALSE),
  (339, 'Each method returns null so calls must be written on separate lines, as in $query->where(...); $query->get()', FALSE),
  (340, 'It creates objects without exposing creation logic; Laravel uses it in View::make, Validator::make and model factories that generate fake models', TRUE),
  (340, 'It creates one shared instance used by all requests; Laravel uses it in Cache::get and Config::get', FALSE),
  (340, 'It copies an object and changes some fields; Laravel uses it in replicate and clone', FALSE),
  (341, 'Manager classes like CacheManager, MailManager and QueueManager create the right driver from configuration, combining Factory and Strategy, and new drivers can be added with extend()', TRUE),
  (341, 'Manager classes like CacheManager hold one fixed driver chosen at install time and cannot be extended', FALSE),
  (341, 'Manager classes like CacheManager create a new database connection for each driver and close it after each query', FALSE),
  (342, 'It defines interchangeable algorithms behind one interface and picks one at runtime; cache, queue, mail and storage drivers are strategies', TRUE),
  (342, 'It defines one algorithm in a base class and lets subclasses change some steps; cache, queue, mail and storage drivers are subclasses', FALSE),
  (342, 'It defines one object that cannot be created twice; cache, queue, mail and storage drivers are singletons', FALSE),
  (343, 'It converts one interface into another that the code expects; Storage uses Flysystem adapters so local disk, S3 and FTP share one API', TRUE),
  (343, 'It wraps an object to add behavior without changing its class; Storage uses decorators so local disk, S3 and FTP are cached', FALSE),
  (343, 'It hides a complex subsystem behind a simple interface; Storage uses a facade so local disk, S3 and FTP are one class', FALSE),
  (344, 'Only one instance of a class exists; Laravel registers the class as a singleton in the container so the same instance is shared, instead of a static getInstance', TRUE),
  (344, 'A new instance is created on each use; Laravel registers the class with bind in the container so each caller gets a fresh one', FALSE),
  (344, 'One instance exists per user session; Laravel stores it in the session so it is shared across requests', FALSE),
  (345, 'A request passes through a chain of handlers that can process, modify or stop it; HTTP middleware calls $next($request) to pass it on', TRUE),
  (345, 'A request is sent to all handlers at the same time and the fastest answer is used; HTTP middleware runs in parallel', FALSE),
  (345, 'A request is saved in a queue and handled later by one worker; HTTP middleware runs after the response', FALSE),
  (346, 'It sends an object through pipes where each one transforms it and passes it on; Laravel uses it for middleware and Pipeline::send($data)->through([...])->thenReturn()', TRUE),
  (346, 'It sends an object to all pipes at once and merges their results; Laravel uses it for jobs and Pipeline::fan($data)->all([...])', FALSE),
  (346, 'It sends an object through a database transaction in several steps; Laravel uses it for migrations and DB::pipe()', FALSE),
  (347, 'It wraps an object to add behavior without changing its class; middleware around a request acts like one, as does a caching layer around a repository', TRUE),
  (347, 'It copies an object and changes some of its fields; middleware around a request clones it for each handler', FALSE),
  (347, 'It converts one interface into another; middleware around a request translates it for each handler', FALSE),
  (348, 'A stand-in object that controls access to the real one; facades proxy calls to container services and lazy loading creates the real resource only when needed', TRUE),
  (348, 'A copy of the real object that is created once per request; facades copy container services and always create the resource at start', FALSE),
  (348, 'A wrapper that adds behavior to every method of the real object; facades add logging and always create the resource at start', FALSE),
  (349, 'Objects subscribe to events of another object; Laravel implements it with Events and Listeners and Model Observers for creating, created, updated and deleted', TRUE),
  (349, 'One object calls another directly on every change; Laravel implements it with controllers calling models inside transactions', FALSE),
  (349, 'Objects poll the database for changes every minute; Laravel implements it with scheduled commands', FALSE),
  (350, 'Events and Listeners are a general publish/subscribe system for any application event; Model Observers group handlers for one Eloquent model lifecycle in one class', TRUE),
  (350, 'Model Observers are a general publish/subscribe system for any event; Events and Listeners group handlers for one Eloquent model lifecycle', FALSE),
  (350, 'They are the same feature; Observers is the older name for Events and Listeners', FALSE),
  (351, 'It wraps a request as an object; queued Jobs are commands that hold their data and a handle method and can be dispatched, queued, retried or chained', TRUE),
  (351, 'It wraps a response as a view; queued Jobs are templates that render data and cannot be retried or chained', FALSE),
  (351, 'It wraps a database query as a string; queued Jobs are raw SQL files that run once and cannot be retried', FALSE),
  (352, 'A base class defines the steps of an algorithm and subclasses override some steps; Form Requests (authorize, rules) and Notifications (via, toMail) follow it', TRUE),
  (352, 'A base class holds a view template and subclasses fill in the variables; Blade layouts and Notifications follow it', FALSE),
  (352, 'A base class creates objects from a template file and subclasses cannot change it; Form Requests and Notifications are final', FALSE),
  (353, 'Local scopes such as scopeActive name and reuse query conditions, as in User::active()->verified()->get(); global scopes apply conditions to every query, like soft deletes', TRUE),
  (353, 'Local scopes apply conditions to every query of the model automatically; global scopes must be called by name each time', FALSE),
  (353, 'Scopes are only used in migrations to name columns, as in User::active()->verified() on the schema', FALSE),
  (354, 'It provides safe default behavior instead of null; optional() and withDefault() on relationships return an empty object so $post->author->name needs no null checks', TRUE),
  (354, 'It stores null in the database instead of empty strings; optional() and withDefault() on relationships delete missing rows', FALSE),
  (354, 'It throws an exception whenever a value is null; optional() and withDefault() on relationships make the exception silent', FALSE),
  (355, 'Classes like Collection, Str, Request and Response use the Macroable trait so you can add custom methods at runtime with Collection::macro(...) without inheritance', TRUE),
  (355, 'Classes like Collection, Str, Request and Response are final, so custom methods can only be added by editing vendor files', FALSE),
  (355, 'Classes like Collection and Str use the Macroable trait to run macros defined in .env files at deploy time', FALSE),
  (356, 'A dedicated class holding validation rules and authorization for a request; type-hinting it in a controller validates before the method runs', TRUE),
  (356, 'A dedicated class holding the HTML form fields for a view; type-hinting it in a controller renders the form before the method runs', FALSE),
  (356, 'A dedicated class holding database queries for a request; type-hinting it in a controller loads the data before the method runs', FALSE),
  (357, 'Gates are closures and Policies are classes holding authorization logic for actions on a model, such as PostPolicy::update, separating who-can-do-what from controllers', TRUE),
  (357, 'Gates are classes and Policies are closures holding validation rules for requests, such as PostPolicy::rules, separating validation from controllers', FALSE),
  (357, 'Gates and Policies are middleware that block routes by IP address, such as PostPolicy::ip, separating networking from controllers', FALSE),
  (358, 'They transform models into JSON responses and act as a Transformer or Presenter layer, so you control which fields are exposed and how they are formatted', TRUE),
  (358, 'They are routes generated for models that return JSON and act as a Router layer, so you control which URLs are exposed', FALSE),
  (358, 'They are database views that return JSON and act as a Repository layer, so you control which columns are queried', FALSE),
  (359, 'A Value Object is a small immutable object defined by its values, like Money; custom casts (CastsAttributes) convert columns to value objects and back', TRUE),
  (359, 'A Value Object is a mutable object with an identity, like User; custom casts (CastsAttributes) convert Eloquent models to arrays', FALSE),
  (359, 'A Value Object is a database row with a primary key, like Money; custom casts (CastsAttributes) convert tables to models', FALSE),
  (360, 'Single Responsibility, Open/Closed, Liskov Substitution, Interface Segregation and Dependency Inversion, guiding clean maintainable class design', TRUE),
  (360, 'Single Responsibility, Open/Closed, Law of Demeter, Inheritance Segregation and Dependency Injection, guiding clean maintainable class design', FALSE),
  (360, 'Simple, Optimized, Linear, Isolated and Dynamic, guiding fast database queries', FALSE),
  (361, 'High-level code depends on interfaces (contracts such as the Cache Repository contract); the container binds each interface to a swappable implementation', TRUE),
  (361, 'High-level code depends on concrete classes such as the file cache; the container hides them behind static facade calls only', FALSE),
  (361, 'Low-level code depends on high-level controllers; the container binds each controller to a swappable model', FALSE),
  (362, 'Interfaces defining the core services of the framework, such as Queue, Mailer and Cache; depending on them keeps code loosely coupled and easy to replace or mock', TRUE),
  (362, 'Legal terms of the license that every Laravel project must accept; depending on them keeps the project compliant', FALSE),
  (362, 'Database constraints defined in migrations, such as unique and foreign; depending on them keeps data valid', FALSE),
  (363, 'It moves logic from controllers into models, but taken too far models become huge God objects; better keep both thin and use services, actions and jobs', TRUE),
  (363, 'It moves logic from models into controllers, but taken too far controllers become huge; better keep models thin and put everything in controllers', FALSE),
  (363, 'It moves logic from the database into models, but taken too far queries become slow; better keep logic in stored procedures', FALSE),
  (364, 'It separates writes (commands or actions that change data) from reads (query classes or read models); often Action classes for writes and dedicated query classes for reads', TRUE),
  (364, 'It separates users into command and query roles, so only some users can write; often done with Policies and Gates', FALSE),
  (364, 'It separates the database into a command and a query connection that always hold different data; often done with read replicas', FALSE),
  (365, 'Start simple with built-in tools like Eloquent, Form Requests, Policies, Jobs and Events, and add Services, Actions, DTOs or Repositories only when complexity justifies them', TRUE),
  (365, 'Apply every known pattern from the start, including Repositories, Services and DTOs for every model, so the project is ready for growth', FALSE),
  (365, 'Avoid built-in tools and write your own classes for each concern, so the project has no dependency on the framework', FALSE);
INSERT INTO academic_item_options (academic_item_id, option_text, is_correct) VALUES
  (379, 'The default place to register container bindings and bootstrap app-wide services, with register() and boot() methods', TRUE),
  (379, 'The default place to define routes and middleware groups for the app, with map() and handle() methods', FALSE),
  (379, 'The default place to store application settings and environment values, with get() and set() methods', FALSE),
  (380, 'register() only binds things into the container and must not use other services; boot() runs after all providers are registered, so any service can be used', TRUE),
  (380, 'register() runs after all providers are booted and can use any service; boot() only binds things into the container', FALSE),
  (380, 'register() runs once per request and boot() runs once per deployment, and both can use any service', FALSE),
  (381, 'The central place to bootstrap the app: core services such as database, queue, validation and routing, and your own, are registered and booted through them', TRUE),
  (381, 'The place where user accounts and roles are created: admins, editors and guests are registered and activated through them', FALSE),
  (381, 'The place where HTTP responses are built: views, JSON and redirects are registered and rendered through them', FALSE),
  (382, 'In config/app.php in Laravel 10 and earlier, and in bootstrap/providers.php in Laravel 11 and later', TRUE),
  (382, 'In bootstrap/providers.php in Laravel 10 and earlier, and in config/app.php in Laravel 11 and later', FALSE),
  (382, 'In composer.json in every version, under an extra providers key', FALSE),
  (383, 'A powerful dependency injection container that manages class dependencies and resolves them automatically; you bind interfaces in a provider and Laravel injects them', TRUE),
  (383, 'A cache of service objects that stores them between requests; you bind interfaces in a provider and Laravel reuses them', FALSE),
  (383, 'A Docker container for the services of the app; you bind ports in a provider and Laravel exposes them', FALSE),
  (384, 'Up to Laravel 10 it defines global middleware, middleware groups such as web and api, and route middleware aliases that every request passes through', TRUE),
  (384, 'Up to Laravel 10 it registers Artisan commands and defines the task schedule used by schedule:run', FALSE),
  (384, 'Since Laravel 11 it is the only place to define routes, jobs and the task schedule', FALSE),
  (385, 'Up to Laravel 10 it registers Artisan commands and defines the task schedule used by php artisan schedule:run', TRUE),
  (385, 'Up to Laravel 10 it defines global middleware and the middleware groups web and api', FALSE),
  (385, 'Since Laravel 11 it defines the database connections used by Artisan commands', FALSE),
  (386, 'Both Kernel files were removed: middleware is set in bootstrap/app.php with withMiddleware(), exceptions with withExceptions() and the schedule in routes/console.php', TRUE),
  (386, 'Both Kernel files were merged into one app/Kernel.php that now holds middleware, exceptions and the schedule', FALSE),
  (386, 'Both Kernel files were moved to config/kernel.php, where middleware, exceptions and the schedule are now set', FALSE),
  (387, 'It creates the application instance and in Laravel 11 configures routing, middleware and exceptions with a fluent API, then returns the app to index.php and artisan', TRUE),
  (387, 'It creates the database connection and in Laravel 11 runs migrations, seeders and the scheduler, then returns the connection to index.php', FALSE),
  (387, 'It creates the HTTP request and in Laravel 11 validates input and authorizes users, then returns the request to the controllers', FALSE),
  (388, 'Introduced in Laravel 11, it returns the array of application service providers such as AppServiceProvider, replacing the providers array of config/app.php', TRUE),
  (388, 'Introduced in Laravel 11, it returns the array of package aliases such as Cache and DB, replacing the aliases array of config/app.php', FALSE),
  (388, 'Introduced in Laravel 11, it returns the array of global middleware such as TrimStrings, replacing the middleware array of the HTTP Kernel', FALSE),
  (389, 'It stores framework-generated cache files such as the services and packages manifests and cached config or routes; it must be writable and can be regenerated', TRUE),
  (389, 'It stores user-uploaded files and compiled views; it must be public and cannot be regenerated', FALSE),
  (389, 'It stores Composer packages and the autoloader; it must be committed to Git and cannot be regenerated', FALSE),
  (390, 'The single entry point of every web request: it loads the Composer autoloader, boots the app and hands the request to the kernel or router, then sends the response', TRUE),
  (390, 'The command line entry point of the app: it boots the framework and runs Artisan commands such as migrate', FALSE),
  (390, 'The file that holds all web routes: it maps URLs to controllers and returns the response', FALSE),
  (391, 'The entry point of the command line interface in the project root: it boots the app and runs Artisan commands such as migrate or make:model', TRUE),
  (391, 'The entry point of every web request in the public folder: it boots the app and hands the request to the router', FALSE),
  (391, 'The file that lists all Artisan commands in a JSON map: Laravel reads it to find which class to run', FALSE),
  (392, 'Environment-specific configuration such as APP_KEY, APP_ENV, APP_DEBUG and database and mail credentials; never commit it, and read it via config files with env()', TRUE),
  (392, 'Shared project configuration such as routes and middleware; commit it so every developer uses the same values, read through the env() helper everywhere', FALSE),
  (392, 'A compiled cache of the config files; commit it to deploy faster, read through the config() helper only', FALSE),
  (393, 'A template of .env with placeholder values committed to the repository; new developers copy it to .env and fill in their own values', TRUE),
  (393, 'A backup of the production .env file with real values committed to the repository so deployments can restore it', FALSE),
  (393, 'A generated file that Laravel creates from .env at boot and that must not be committed or edited', FALSE),
  (394, 'When config is cached with config:cache the .env file is no longer loaded, so env() outside config files returns null; use config() elsewhere', TRUE),
  (394, 'Because env() is slower than config() and logs a warning in production, though it still returns the correct value after caching', FALSE),
  (394, 'Because env() can only read values defined in the .env.example file, and config() reads those in .env', FALSE),
  (395, 'Core application settings: name, env, debug, url, timezone, locale, encryption key and cipher, and maintenance mode driver', TRUE),
  (395, 'Database connection settings: host, port, username, password, charset and the default connection name', FALSE),
  (395, 'Authentication settings: guards, user providers, password reset rules and the timeout for confirmation', FALSE),
  (396, 'It holds all configuration files such as app, database, cache, queue, mail, filesystems and session, read with config(file.key) and usually fed from .env', TRUE),
  (396, 'It holds all migration files for the database, run with php artisan migrate and usually seeded from .env', FALSE),
  (396, 'It holds all translation files for the app, read with __(file.key) and usually fed from .env', FALSE),
  (397, 'It defines web routes loaded with the web middleware group, which provides sessions, cookies, CSRF protection and view-related features', TRUE),
  (397, 'It defines stateless API routes loaded with the api middleware group, which provides throttling and no sessions', FALSE),
  (397, 'It defines broadcast channels loaded with the channels middleware group, which provides authorization callbacks', FALSE),
  (398, 'It defines stateless API routes with the api prefix and middleware group (throttling, no sessions); in Laravel 11 it is created with php artisan install:api', TRUE),
  (398, 'It defines web routes with the web prefix and middleware group (sessions, CSRF); in Laravel 11 it is created with php artisan install:web', FALSE),
  (398, 'It defines console routes with the console prefix and middleware group (schedule, queue); in Laravel 11 it is created with php artisan install:console', FALSE),
  (399, 'It defines closure-based Artisan commands and, in Laravel 11 and later, scheduled tasks using Schedule::command() or Schedule::call()', TRUE),
  (399, 'It defines closure-based web routes and, in Laravel 11 and later, middleware groups using Route::middleware() or Route::group()', FALSE),
  (399, 'It defines closure-based event listeners and, in Laravel 11 and later, queue workers using Queue::work() or Queue::listen()', FALSE),
  (400, 'It registers event broadcasting channels and their authorization callbacks, used with Laravel Echo, Reverb or Pusher for real-time features', TRUE),
  (400, 'It registers console command channels and their output formats, used with Artisan, Horizon or Telescope for queue monitoring', FALSE),
  (400, 'It registers notification channels such as mail and SMS and their rate limits, used with Mailgun or Twilio for delivery', FALSE),
  (401, 'In Laravel 10 and earlier it loads route files, defines the HOME constant and configures rate limiters; in Laravel 11 route loading moved to bootstrap/app.php', TRUE),
  (401, 'In Laravel 10 and earlier it registers policies and gates; in Laravel 11 policy registration moved to bootstrap/app.php', FALSE),
  (401, 'In Laravel 10 and earlier it maps events to listeners; in Laravel 11 event mapping moved to bootstrap/app.php', FALSE),
  (402, 'It registers model policies and gates for authorization; in Laravel 11 and later policies are auto-discovered and the provider is no longer in the default skeleton', TRUE),
  (402, 'It registers login routes and authentication guards; in Laravel 11 and later guards are loaded from routes/auth.php instead', FALSE),
  (402, 'It registers user models and password hashers; in Laravel 11 and later hashers are set in config/hashing.php only', FALSE),
  (403, 'It maps events to listeners and registers model observers; since Laravel 11 events and listeners are auto-discovered, so it is not in the default skeleton', TRUE),
  (403, 'It maps routes to controllers and registers route model bindings; since Laravel 11 routes are auto-discovered, so it is not in the default skeleton', FALSE),
  (403, 'It maps jobs to queues and registers failed job handlers; since Laravel 11 jobs are auto-discovered, so it is not in the default skeleton', FALSE),
  (404, 'It registers broadcasting routes with Broadcast::routes() and loads routes/channels.php; in Laravel 11 it is enabled with php artisan install:broadcasting', TRUE),
  (404, 'It registers notification routes with Notification::routes() and loads routes/notifications.php; in Laravel 11 it is enabled with php artisan install:notifications', FALSE),
  (404, 'It registers web socket servers with Socket::serve() and loads config/sockets.php; in Laravel 11 it is enabled with php artisan install:sockets', FALSE),
  (405, 'In Laravel 10 and earlier it is the central place to report and render exceptions, with report and render methods and a $dontReport list; in Laravel 11 use withExceptions() in bootstrap/app.php', TRUE),
  (405, 'In Laravel 10 and earlier it is the central place to define middleware aliases and groups; in Laravel 11 use withMiddleware() in bootstrap/app.php', FALSE),
  (405, 'In Laravel 10 and earlier it is the central place to register Artisan commands; in Laravel 11 use withCommands() in bootstrap/app.php', FALSE),
  (406, 'It holds middleware classes that filter HTTP requests, such as Authenticate, VerifyCsrfToken, TrimStrings, TrustProxies and EncryptCookies; in Laravel 11 most are built in', TRUE),
  (406, 'It holds validation classes that filter request fields, such as Authenticate, VerifyCsrfToken and TrimStrings; in Laravel 11 they are replaced by Form Requests', FALSE),
  (406, 'It holds guard classes that filter console commands, such as Authenticate and TrimStrings; in Laravel 11 they are replaced by Policies', FALSE),
  (407, 'It holds controller classes that handle requests and return responses; keep them thin and move business logic into services, actions or jobs', TRUE),
  (407, 'It holds model classes that map to tables; keep them thin and move business logic into controllers', FALSE),
  (407, 'It holds view classes that render Blade templates; keep them thin and move HTML into controllers', FALSE),
  (408, 'It contains Eloquent model classes, each representing a table, defining relationships, casts, fillable attributes, scopes and accessors', TRUE),
  (408, 'It contains migration classes, each creating a table, defining columns, indexes, foreign keys and default values', FALSE),
  (408, 'It contains seeder classes, each filling a table, defining fake rows, factories, counts and relations', FALSE),
  (409, 'composer.json lists PHP dependencies, autoload rules and scripts; composer.lock pins the exact installed versions so every environment gets the same packages; commit both', TRUE),
  (409, 'composer.json pins the exact installed versions; composer.lock lists PHP dependencies, autoload rules and scripts; commit only the lock file', FALSE),
  (409, 'composer.json lists front-end packages and scripts; composer.lock lists the PHP version only; commit neither', FALSE),
  (410, 'It stores Composer-installed packages, including the Laravel framework and autoload.php; it is generated by composer install and should not be committed to Git', TRUE),
